function modalHeader(eyebrow,title,subtitle=''){return `<div class="modal-header"><div><div class="eyebrow">${eyebrow}</div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-button" data-close aria-label="关闭">${icon('close')}</button></div>`;}
function pageHeading(en,title,sub,note=''){
 const titles={atelier:'调香工作台',explore:'香水图鉴',today:'今日选香',collection:'我的香气'},symbols={atelier:'bottle',explore:'book',today:'sun',collection:'archive'};
 const stats=route==='explore'?[[perfumes.length.toLocaleString(),'香水档案'],[catalogBrands.length.toLocaleString(),'品牌']]:route==='collection'?[[owned.length,'我的香水'],[works.length,'调香作品']]:[];
 return `<div class="page-heading"><div class="page-title-group"><span class="heading-mark" aria-hidden="true">${icon(symbols[route]||'bottle')}</span><div><h1>${titles[route]||title}</h1><p class="intro">${route==='explore'?'从熟悉的香气，发现新的喜欢。':sub}</p></div></div>${stats.length?`<div class="page-stats">${stats.map(([value,label])=>`<span><strong>${value}</strong><small>${label}</small></span>`).join('')}</div>`:''}</div>`;
}
